const targets: number[] = [];
let page = 1;
while (page <= 100) {
  const res: any = await tools.list_issues({ repo: "acme/cli", state: "open", page });
  const items: any[] = Array.isArray(res) ? res : (res?.items ?? res?.issues ?? []);
  if (!items.length) break;
  for (const i of items) {
    const labels = Array.isArray(i.labels) ? i.labels : [];
    if (labels.length === 0 && !i.pull_request) targets.push(i.number);
  }
  if (items.length < 50) break;
  page++;
}
const unique = [...new Set(targets)];
const failed: any[] = [];
let ok = 0;
for (const n of unique) {
  try {
    await tools.add_label({ repo: "acme/cli", number: n, label: "needs-triage" });
    ok++;
  } catch (e: any) {
    failed.push({ number: n, error: String(e?.message ?? e) });
  }
}
return { pages: page, count: unique.length, ok, numbers: unique, failed };
```

